30	namespace fs = std::filesystem;
31	
32	namespace andes_sim {
33	namespace {
34	
35	// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
36	// feed the summary, and only FAIL gates the exit code.
37	struct Row {
38	  std::string name;
39	  std::string status;
40	  std::string detail;
41	};
42	
43	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
44	std::string strip_char(std::string s, char c) {
45	  size_t b = 0, e = s.size();
46	  while (b < e && s[b] == c) ++b;
47	  while (e > b && s[e - 1] == c) --e;
48	  return s.substr(b, e - b);
49	}
50	
51	// --- artifacts --------------------------------------------------------------
52	
53	std::vector<Row> doctor_artifacts() {
54	  const fs::path root = repo_root();
55	  struct A {
56	    const char* label;
57	    const char* env;
58	    fs::path def;
59	  };
60	  // qemu default mirrors builtin_qemu: $QEMU_BIN_DIR (env or config.env) holds
61	  // the external qemu-system-riscv64; fall back to the legacy in-tree build.
62	  const std::string qbd = config_env_value("QEMU_BIN_DIR");
63	  const fs::path qemu_def = qbd.empty()
64	                                ? root / "build" / "qemu" / "qemu-system-riscv64"
65	                                : fs::path(qbd) / "qemu-system-riscv64";
66	  // Env overrides match hsim's _ARTIFACT_ENV so a test can simulate a missing
67	  // binary. Order (vsim, qemu, plugin) mirrors the golden's dict order.
68	  const A arts[] = {
69	      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
70	      {"qemu64", "VSIM_QEMU", qemu_def},
71	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
72	  };
73	  std::vector<Row> rows;
74	  for (const A& a : arts) {
75	    const char* ov = std::getenv(a.env);
76	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
77	    if (fs::is_regular_file(p))
78	      rows.push_back({a.label, "PASS", p.string()});
79	    else
80	      rows.push_back(
81	          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
82	  }
83	
84	  const fs::path fix = root / "tests" / "fixtures";
85	  size_t elfs = 0;
86	  std::error_code ec;
87	  if (fs::is_directory(fix, ec))
88	    for (const auto& e : fs::directory_iterator(fix, ec))
89	      if (e.path().extension() == ".elf") ++elfs;
90	  if (elfs > 0)
91	    rows.push_back(
92	        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
93	  else
94	    rows.push_back({"fixtures", "FAIL",
95	                    "no *.elf in " + fix.string() +
96	                        " -- run make -C tests/fixtures"});
97	  return rows;
98	}
99	
100	// --- submodules -------------------------------------------------------------
101	
102	std::vector<Row> doctor_submodules() {
103	  const fs::path root = repo_root();
104	  struct M {
105	    const char* name;
106	    fs::path marker;
107	    const char* rel;  // marker, repo-relative (the PASS detail)
108	  };
109	  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
110	  // external binaries, checked in the artifacts section (qemu/vsim rows) via
111	  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
112	  const M ms[] = {
113	      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
114	       "include/hybrid/state_abi.h"},
115	  };
116	  std::vector<Row> rows;
117	  for (const M& m : ms) {
118	    if (fs::is_regular_file(m.marker))
119	      rows.push_back({m.name, "PASS", m.rel});
120	    else
121	      rows.push_back({m.name, "FAIL",
122	                      "missing " + m.marker.string() +
123	                          " -- run 'git submodule update --init --recursive'"});
124	  }
125	  return rows;
126	}
127	
128	// --- toolchain --------------------------------------------------------------
129	
130	// First PATH directory holding an executable non-directory named `tool`, joined
131	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
132	std::string which(const std::string& tool) {
133	  const char* path = std::getenv("PATH");
134	  if (!path) return "";
135	  const std::string p(path);
136	  for (size_t i = 0; i <= p.size();) {
137	    size_t j = p.find(':', i);
138	    if (j == std::string::npos) j = p.size();
139	    std::string dir = p.substr(i, j - i);
140	    i = j + 1;
141	    if (dir.empty()) continue;
142	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
143	    std::error_code ec;
144	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
145	      return cand;
146	  }
147	  return "";
148	}
149	
150	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
151	// to the value with surrounding whitespace, then double, then single quotes
152	// stripped (mirrors hsim._read_hybrid_toolchain).
153	bool parse_toolchain_line(const std::string& line, std::string& out) {
154	  size_t i = 0, n = line.size();
155	  auto skip_ws = [&] {
156	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
157	  };
158	  skip_ws();
159	  const std::string kw = "export";
160	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
161	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
162	    i += kw.size();
163	    skip_ws();
164	  }
165	  const std::string key = "HYBRID_TOOLCHAIN";
166	  if (line.compare(i, key.size(), key) != 0) return false;
167	  i += key.size();
168	  skip_ws();
169	  if (i >= n || line[i] != '=') return false;
170	  std::string rest = line.substr(i + 1);  // everything after '='
171	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
172	  size_t b = 0, e = rest.size();
173	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
174	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
175	  std::string val = strip_char(rest.substr(b, e - b), '"');
176	  out = strip_char(val, '\'');
177	  return true;
178	}
179	
180	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
181	// assignment in config.env. "" if neither yields a value.
182	std::string read_hybrid_toolchain() {
183	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
184	  if (env && *env) return env;
185	  std::ifstream f(repo_root() / "config.env");
186	  if (!f) return "";
187	  std::string line, val;
188	  while (std::getline(f, line))
189	    if (parse_toolchain_line(line, val)) return val;
190	  return "";
191	}
192	
193	std::vector<Row> doctor_toolchain() {
194	  struct T {
195	    const char* tool;
196	    const char* hint;
197	    bool warn_only;  // a missing podman warns; ninja/make fail
198	  };
199	  const T tools[] = {
200	      {"ninja", "needed by scripts/build_all.sh of QEMU", false},
201	      {"make", "needed by scripts/build_all.sh of fixtures", false},
202	      {"podman", "needed by scripts/build_all.sh of vsim (or docker shim)", true},
203	  };
204	  std::vector<Row> rows;
205	  for (const T& t : tools) {
206	    std::string found = which(t.tool);
207	    if (!found.empty())
208	      rows.push_back({t.tool, "PASS", found});
209	    else
210	      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
211	                      std::string("not on PATH -- ") + t.hint});
212	  }
213	
214	  std::string tc = read_hybrid_toolchain();
215	  if (tc.empty()) {
216	    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
217	                    "not set -- needed for fixture build (see config.env)"});
218	  } else {
219	    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
220	    if (fs::is_regular_file(gcc))
221	      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
222	    else
223	      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
224	                      "missing " + gcc.string() +
225	                          " -- check HYBRID_TOOLCHAIN=" + tc});
226	  }
227	  return rows;
228	}
229	
230	// --- runtime ----------------------------------------------------------------
231	
232	constexpr long kDefaultJobs = 8;
233	
234	std::vector<Row> doctor_runtime() {
235	  std::vector<Row> rows;
236	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
237	  if (nproc < 1) nproc = 1;
238	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
239	
240	  std::error_code ec;
241	  if (fs::is_directory("/dev/shm", ec)) {
242	    struct statvfs vfs{};
243	    unsigned long long free_gb = 0;
244	    if (statvfs("/dev/shm", &vfs) == 0)
245	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
246	                (1024ULL * 1024 * 1024);
247	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
248	                    std::to_string(free_gb) + " GB"});
249	  } else {
250	    rows.push_back({"/dev/shm", "WARN",
251	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
252	  }
253	
254	  long suggested = std::min(nproc, kDefaultJobs);
255	  rows.push_back({"JOBS suggestion", "INFO",
256	                  std::to_string(suggested) + " (default cap = " +
257	                      std::to_string(kDefaultJobs) + ")"});
258	  return rows;
259	}
260	
261	// --- engines (C++-only readout, after Summary) ------------------------------
262	
263	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
264	// INFO-tagged and printed after Summary, so it never moves the summary counts
265	// or the exit code. Discovery warnings surface as WARN rows here.
266	void print_engines_section() {
267	  Discovery disc = discover_engines();
268	  size_t w = 0;
269	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
270	
271	  std::printf("\nengines:\n");
272	  for (const EngineDescriptor& e : disc.engines)
273	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
274	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
275	                join(e.triggers).c_str());
276	  for (const std::string& warn : disc.warnings)
277	    std::printf("  [WARN] %s\n", warn.c_str());
278	}
279	
280	// The shared-mmap backing tiers (F1 resolver order) with their free space,
281	// plus WSL2 advice. INFO/WARN-tagged and printed after Summary like engines,
282	// so the carried-over report keeps byte-parity with the Python golden.
283	void print_mmap_section() {
284	  const std::vector<MmapTier> tiers = mmap_tiers();
285	  size_t w = 0;
286	  for (const MmapTier& t : tiers) w = std::max(w, t.label.size());
287	
288	  std::printf("\nmmap tiers:\n");
289	  int n = 0;
290	  for (const MmapTier& t : tiers) {
291	    struct statvfs vfs{};
292	    std::string free = "missing";
293	    if (statvfs(t.dir.c_str(), &vfs) == 0) {
294	      const double gib = static_cast<double>(vfs.f_bavail) * vfs.f_frsize /
295	                         (1024.0 * 1024 * 1024);
296	      char buf[32];
297	      std::snprintf(buf, sizeof(buf), "free: %.1f GiB", gib);
298	      free = buf;
299	    }
300	    std::printf("  [INFO] tier %d  %s  %s\n", ++n, ljust(t.label, w).c_str(),
301	                free.c_str());
302	  }
303	
304	  std::string proc_version;
305	  if (std::FILE* f = std::fopen("/proc/version", "r")) {
306	    char buf[512] = {};
307	    const size_t got = std::fread(buf, 1, sizeof(buf) - 1, f);
308	    proc_version.assign(buf, got);
309	    std::fclose(f);
310	  }
311	  std::error_code ec;
312	  for (const std::string& warn :
313	       wsl_warnings(proc_version, fs::current_path(ec).string(), tiers))
314	    std::printf("  [WARN] %s\n", warn.c_str());
315	}
316	
317	struct Section {
318	  const char* title;
319	  std::vector<Row> rows;
320	};
321	
322	}  // namespace
323	
324	int cmd_doctor(const Cli&) {
325	  std::vector<Section> sections = {
326	      {"artifacts", doctor_artifacts()},
327	      {"submodules", doctor_submodules()},
328	      {"toolchain", doctor_toolchain()},
329	      {"runtime", doctor_runtime()},
330	  };
331	
332	  size_t name_width = 0;
333	  for (const Section& s : sections)
334	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
335	
336	  int passes = 0, fails = 0, warns = 0;
337	  for (const Section& s : sections) {
338	    std::printf("%s:\n", s.title);
339	    for (const Row& r : s.rows) {
340	      if (r.status == "PASS") ++passes;
341	      else if (r.status == "FAIL") ++fails;
342	      else if (r.status == "WARN") ++warns;
343	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
344	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
345	    }
346	    std::printf("\n");
347	  }
348	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
349	
350	  print_engines_section();
351	  print_mmap_section();
352	  return fails > 0 ? 1 : 0;
353	}
354	
355	}  // namespace andes_sim
356

